using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace CommonHouse.Outpost
{
    /// <summary>
    /// The deliberately small, present-day blockout for the Case 01 outpost.
    /// Its geometry is generated by the Editor tool so temporary primitives do
    /// not become hand-edited scene data.
    /// </summary>
    public sealed class OutpostLayout : MonoBehaviour
    {
        public const string ScenePath = "Assets/CommonHouse/Scenes/OutpostBlockout.unity";
        public const string RadioRoom = "RadioRoom";
        public const string Kitchen = "Kitchen";
        public const string ArchiveWorkshop = "ArchiveWorkshop";

        public static readonly Bounds PresentDayBounds = new Bounds(Vector3.up * 1.5f, new Vector3(28f, 3f, 8f));

        public static readonly IReadOnlyList<string> RequiredAnchorIds = new[]
        {
            "radio-console",
            "radio-receiver",
            "kitchen-table",
            "archive-roster",
            "workshop-bench",
            "routing-switch",
        };

        public static readonly IReadOnlyList<Vector3> TraversalPoints = new[]
        {
            new Vector3(-10f, 1f, 0f),
            new Vector3(0f, 1f, 0f),
            new Vector3(10f, 1f, 0f),
        };

        public IEnumerable<OutpostAnchor> Anchors => GetComponentsInChildren<OutpostAnchor>(true);

        public bool ContainsPresentDayPoint(Vector3 point) => PresentDayBounds.Contains(point);

        public OutpostAnchor GetAnchor(string id)
        {
            return Anchors.SingleOrDefault(anchor => anchor.AnchorId == id);
        }
    }

}
